window.products.push({"id":1115225,"name":"Pedrini Wine & Bar ABS Foil Cutter","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/3187MSV27XL._AC_.jpg","description":"Product Description Pedrini's Wine and Bar selection is dedicated to the Art of Drinking! The unmistakable Pedrini design uses the brilliance of steel with stylish silver colour accents and becomes the perfect companion of the magic and friendly atmosphere of your home bar. Translucent ABS foil cutter with carbon steel cutting wheels. Amazon.com Before toasting to friends and family, the wine bottle must be opened--and this handy foil cutter makes it easy. Four circular, stainless-steel blades fit over most bottle openings to cut through foil wrappings and expose the cork beneath. An oval-shaped holder made of translucent plastic houses the blades and provides both a comfortable hold and a safeguard to keep fingers from getting cut. This Italian-made gadget measures 3-1/4 by 1/3 by 1-1/2 inches, cleans safely in the dishwasher, and comes with a lifetime warranty. -- Amy Arnold","images":["https://m.media-amazon.com/images/I/3187MSV27XL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Pedrini","source_asin":"B0002AKN28","category_path":"Home & Kitchen"},"sku":"BM-1115225","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0002AKN28","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0002AKN28","price_pending":true,"merchant_ready":false});
